def number_the_payments(apps, schema_editor):
    """Each payment keeps the receipt number it had: R1, R2 ... on its job, in the order the payments were recorded."""
    Payment = apps.get_model("crm", "Payment")
    counts = {}
    for payment in Payment.objects.order_by("job_id", "id"):
        counts[payment.job_id] = counts.get(payment.job_id, 0) + 1
        payment.number = counts[payment.job_id]
        payment.save(update_fields=["number"])


